import type { Snippet } from "svelte";
import type {
  HTMLAnchorAttributes,
  HTMLButtonAttributes,
  HTMLInputAttributes,
  SvelteHTMLElements,
} from "svelte/elements";

export type ToolbarOrientation = "horizontal" | "vertical";
export type ToolbarRootState = {
  disabled: boolean;
  orientation: ToolbarOrientation;
};
export type ToolbarLinkState = { orientation: ToolbarOrientation };

type PartProps<Args extends unknown[] = [], Tag extends "a" | "button" | "div" = "div"> = Omit<
  Tag extends "a"
    ? HTMLAnchorAttributes
    : Tag extends "button"
      ? HTMLButtonAttributes
      : SvelteHTMLElements["div"],
  "children" | "id"
> & {
  as?: keyof HTMLElementTagNameMap;
  children?: Snippet<Args>;
  id?: string;
  ref?: HTMLElement | null;
};

export type ToolbarRootProps = PartProps<[ToolbarRootState]> & {
  disabled?: boolean;
  loopFocus?: boolean;
  orientation?: ToolbarOrientation;
};
export type ToolbarButtonProps = PartProps<[ToolbarRootState], "button"> & {
  disabled?: boolean;
};
export type ToolbarGroupProps = PartProps<[ToolbarRootState]> & { disabled?: boolean };
export type ToolbarInputProps = Omit<HTMLInputAttributes, "children" | "disabled"> & {
  disabled?: boolean;
  ref?: HTMLInputElement | null;
};
export type ToolbarLinkProps = PartProps<[ToolbarLinkState], "a">;
export type ToolbarSeparatorProps = Omit<PartProps, "children"> & {
  orientation?: ToolbarOrientation;
};

export { Toolbar as ToolbarPrimitive } from "@shardsui/svelte";
export type {
  ToolbarButtonProps,
  ToolbarGroupProps,
  ToolbarInputProps,
  ToolbarLinkProps,
  ToolbarLinkState,
  ToolbarOrientation,
  ToolbarRootProps,
  ToolbarRootState,
  ToolbarSeparatorProps,
} from "./toolbar.types.js";
export { default as Button, default as ToolbarButton } from "./toolbar-button.svelte";
export { default as Group, default as ToolbarGroup } from "./toolbar-group.svelte";
export { default as Input, default as ToolbarInput } from "./toolbar-input.svelte";
export { default as Link, default as ToolbarLink } from "./toolbar-link.svelte";
export { default as Root, default as Toolbar, default as ToolbarRoot } from "./toolbar-root.svelte";
export { default as Separator, default as ToolbarSeparator } from "./toolbar-separator.svelte";
